import zipfile, re, json, os, glob
import xml.etree.ElementTree as ET
NS={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main','r':'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
def col2i(c):
    n=0
    for ch in c: n=n*26+ord(ch)-64
    return n-1
def read(path):
    z=zipfile.ZipFile(path)
    ss=[]
    if 'xl/sharedStrings.xml' in z.namelist():
        r=ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in r.findall('m:si',NS):
            ss.append(''.join(t.text or '' for t in si.iter('{%s}t'%NS['m'])))
    wb=ET.fromstring(z.read('xl/workbook.xml'))
    rels=ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rmap={x.get('Id'):x.get('Target') for x in rels}
    out={}
    for s in wb.find('m:sheets',NS):
        name=s.get('name'); rid=s.get('{%s}id'%NS['r'])
        t=rmap[rid]; t=t.lstrip('/'); 
        if not t.startswith('xl/'): t='xl/'+t
        sh=ET.fromstring(z.read(t))
        rows=[]
        for row in sh.iter('{%s}row'%NS['m']):
            vals={}
            for c in row.findall('m:c',NS):
                ref=c.get('r'); ci=col2i(re.match(r'[A-Z]+',ref).group())
                typ=c.get('t'); v=c.find('m:v',NS)
                if typ=='s': val=ss[int(v.text)]
                elif typ=='inlineStr': val=''.join(t.text or '' for t in c.iter('{%s}t'%NS['m']))
                else: val=v.text if v is not None else None
                vals[ci]=val
            if vals:
                m=max(vals); rows.append([vals.get(i) for i in range(m+1)])
        out[name]=rows
    return out
if __name__=='__main__':
    res={}
    for p in sorted(glob.glob('/app/feed/xlsx/*.xlsx')):
        res[os.path.basename(p)[:-5]]=read(p)
    json.dump(res,open('/app/feed/raw.json','w'))
    print(len(res))
